INSERT INTO changelog (title, body, created_at) VALUES ('Стратегія — тільки головне', 'Огляд Стратегії тепер чистий: Ціль (куди йдемо, натисни — змінити), Шлях (дірки → червоні → жовті → зелені) і Дошка. Старі плитки (Головне зараз, Де ми, тиждень/місяць, висновки, екосистема) прибрані з огляду — дані нікуди не ділись, вони в підвкладках зверху: Екосистема, План, Хроніка, Знання, Висновки.', datetime('now'));
